export const PASSIVES={health:{name:'生息',label:'生命回复',unit:' / 秒',values:[0,.5,1,1.5,2,2.5],icon:0,description:'持续恢复出战英雄生命。候补角色不回复。'},mana:{name:'灵泉',label:'法力回复',unit:' / 秒',values:[0,.25,.5,.8,1.2,1.8],icon:1,description:'恢复出战英雄法力，零级没有基础自动回蓝。'},crit:{name:'破绽洞察',label:'额外暴击率',unit:'%',values:[0,2,4,6,8,10],icon:2,description:'增加所有已拥有及以后获得英雄的暴击几率。'},critDamage:{name:'摧锋',label:'额外暴击伤害',unit:'%',values:[0,8,16,24,32,40],icon:3,description:'只强化暴击命中，普通命中不增加伤害。'}};
export const PASSIVE_COSTS=[300,700,1400,2600,4500];
export function normalizePassives(raw){return Object.fromEntries(Object.keys(PASSIVES).map(k=>[k,Number.isInteger(raw?.[k])?Math.max(0,Math.min(5,raw[k])):0]));}
export function passiveBonuses(profile){const levels=normalizePassives(profile?.passives);return {regen:PASSIVES.health.values[levels.health],manaRegen:PASSIVES.mana.values[levels.mana],crit:PASSIVES.crit.values[levels.crit]/100,critDamage:PASSIVES.critDamage.values[levels.critDamage]/100};}
export function upgradePassive(profile,id){const d=PASSIVES[id];if(!d)throw Error('未知被动技能');const levels=normalizePassives(profile.passives),level=levels[id];if(level>=5)throw Error('已达到五级上限');const cost=PASSIVE_COSTS[level];if(profile.coins<cost)throw Error('金币不足');profile.coins-=cost;levels[id]++;profile.passives=levels;return d.name+'提升至'+levels[id]+'级 · 全角色生效';}
